local HarpoonMaker = {}
local PRODUCTS = {
    simple_iron_harpoon = { name = "Preprost železen harpuna", ironCost = 2, woodCost = 2, ropeCost = 1, time = 4, cost = 80, food = 18, happiness = 1, description = "Preprost železen harpuna za kitolov." },
    steel_barbed_harpoon = { name = "Jeklenobodena harpuna", ironCost = 2, steelCost = 1, woodCost = 2, ropeCost = 1, time = 6, cost = 220, food = 30, happiness = 2, prestige = 2, description = "Jeklenobodena harpuna za trgovce." },
    silver_inlaid_harpoon = { name = "Srebrnovložena harpuna", ironCost = 2, silverCost = 1, steelCost = 1, woodCost = 2, ropeCost = 1, time = 9, cost = 540, food = 45, happiness = 2, prestige = 6, description = "Srebrnovložena harpuna za plemiče." },
    gold_trimmed_harpoon = { name = "Zlatookrasna harpuna", ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, woodCost = 2, ropeCost = 1, time = 13, cost = 1300, food = 60, happiness = 3, prestige = 14, description = "Zlatookrasna harpuna za visoke plemiče." },
    jewel_set_harpoon = { name = "Draguljasta harpuna", ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, woodCost = 2, ropeCost = 1, jewelCost = 1, time = 17, cost = 2900, food = 78, happiness = 5, prestige = 27, description = "Harpuna z draguljem za visoko plemstvo." },
    royal_grand_harpoon = { name = "Kraljevski veliki harpuna", ironCost = 3, goldCost = 2, silverCost = 2, steelCost = 1, woodCost = 2, ropeCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 6200, food = 95, happiness = 12, prestige = 58, description = "Velika kraljevska harpuna z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    harpoon_workshop = { name = "Harpunarska delavnica", cost = { gold = 260, wood = 140, stone = 120, iron = 6, rope = 4 }, upkeep = 6, qualityBonus = 5 },
    fishing_loft = { name = "Ribiška podstrešje", cost = { gold = 950, wood = 280, stone = 240, silver = 6, iron = 6 }, upkeep = 22, qualityBonus = 18 },
    master_harpoon_atelier = { name = "Mojstrski harpunarski atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_fishery_palace = { name = "Kraljevska ribiška palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
HarpoonMaker.ironStock = 14; HarpoonMaker.steelStock = 8; HarpoonMaker.woodStock = 14; HarpoonMaker.ropeStock = 10; HarpoonMaker.silverStock = 6; HarpoonMaker.goldStock = 6; HarpoonMaker.jewelStock = 4; HarpoonMaker.pearlStock = 4
HarpoonMaker.productStock = {}; HarpoonMaker.buildings = {}; HarpoonMaker.maker = nil; HarpoonMaker.activeMaking = {}; HarpoonMaker.totalProducts = 0; HarpoonMaker.dayTimer = 0
function HarpoonMaker.init() HarpoonMaker.ironStock=14; HarpoonMaker.steelStock=8; HarpoonMaker.woodStock=14; HarpoonMaker.ropeStock=10; HarpoonMaker.silverStock=6; HarpoonMaker.goldStock=6; HarpoonMaker.jewelStock=4; HarpoonMaker.pearlStock=4; HarpoonMaker.productStock={}; HarpoonMaker.buildings={}; HarpoonMaker.maker=nil; HarpoonMaker.activeMaking={}; HarpoonMaker.totalProducts=0; HarpoonMaker.dayTimer=0; print("[HarpoonMaker] Royal Harpoon Maker System initialized (6 products, 4 buildings)") end
function HarpoonMaker.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HarpoonMaker.maker={name=n or ("Harpunar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Harpunar najet: %s (spretnost: %d)",HarpoonMaker.maker.name,s),"success") end; return true end
function HarpoonMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HarpoonMaker.build(id) local ok,e=HarpoonMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HarpoonMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HarpoonMaker.getQualityBonus() local b=0; for _,bd in ipairs(HarpoonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HarpoonMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HarpoonMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and HarpoonMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and HarpoonMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and HarpoonMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and HarpoonMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HarpoonMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HarpoonMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HarpoonMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HarpoonMaker.buildings==0 then return false,"Potrebna harpunarska delavnica" end; if not HarpoonMaker.maker then return false,"Potreben harpunar" end; return true end
function HarpoonMaker.make(pt,qty) qty=qty or 1; local ok,e=HarpoonMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HarpoonMaker.ironStock=HarpoonMaker.ironStock-d.ironCost*qty end; if d.steelCost then HarpoonMaker.steelStock=HarpoonMaker.steelStock-d.steelCost*qty end; if d.woodCost then HarpoonMaker.woodStock=HarpoonMaker.woodStock-d.woodCost*qty end; if d.ropeCost then HarpoonMaker.ropeStock=HarpoonMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then HarpoonMaker.silverStock=HarpoonMaker.silverStock-d.silverCost*qty end; if d.goldCost then HarpoonMaker.goldStock=HarpoonMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HarpoonMaker.jewelStock=HarpoonMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HarpoonMaker.pearlStock=HarpoonMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HarpoonMaker.maker then t=math.max(1,t-math.floor(HarpoonMaker.maker.skill/13)) end; table.insert(HarpoonMaker.activeMaking,{id="harpoon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HarpoonMaker.completeMaking(m) local q=1.0+(HarpoonMaker.getQualityBonus()/100); if HarpoonMaker.maker then q=q+(HarpoonMaker.maker.skill/140) end; q=math.min(2.5,q); HarpoonMaker.productStock[m.productType]=(HarpoonMaker.productStock[m.productType] or 0)+m.quantity; HarpoonMaker.totalProducts=HarpoonMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HarpoonMaker.maker then HarpoonMaker.maker.itemsMade=HarpoonMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HarpoonMaker.maker.skill=math.min(100,HarpoonMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Harpuna izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"harpoon.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function HarpoonMaker.update(dt) if not _G.state then return end; HarpoonMaker.dayTimer=HarpoonMaker.dayTimer+dt; if HarpoonMaker.dayTimer>=30 then HarpoonMaker.dayTimer=0; for i=#HarpoonMaker.activeMaking,1,-1 do local m=HarpoonMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HarpoonMaker.completeMaking(m); table.remove(HarpoonMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HarpoonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HarpoonMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HarpoonMaker.getStats() return {ironStock=HarpoonMaker.ironStock,steelStock=HarpoonMaker.steelStock,woodStock=HarpoonMaker.woodStock,ropeStock=HarpoonMaker.ropeStock,silverStock=HarpoonMaker.silverStock,goldStock=HarpoonMaker.goldStock,jewelStock=HarpoonMaker.jewelStock,pearlStock=HarpoonMaker.pearlStock,productStock=HarpoonMaker.productStock,numBuildings=#HarpoonMaker.buildings,hasMaker=HarpoonMaker.maker~=nil,makerName=HarpoonMaker.maker and HarpoonMaker.maker.name or "—",makerSkill=HarpoonMaker.maker and HarpoonMaker.maker.skill or 0,activeMaking=#HarpoonMaker.activeMaking,totalProducts=HarpoonMaker.totalProducts} end
return HarpoonMaker
